fix.code:
final class AuditedTagSet {
    private final Set<String> tags = new HashSet<>();
    private int addedCount = 0;

    boolean add(String tag) {
        addedCount++;
        return tags.add(tag);
    }

    void addAll(Collection<String> newTags) {
        newTags.forEach(this::add);   // đếm ở đúng một chỗ, do mình kiểm soát
    }

    int addedCount() { return addedCount; }
    Set<String> view() { return Collections.unmodifiableSet(tags); }
}
